// The theme manifest is generated by scripts/build-theme.ts; these tests pin the
// contract the board and HUD rely on: every semantic key resolves, and every
// manifest URL points at a real file under public/.

import { existsSync } from 'node:fs'
import path from 'node:path'
import { ACTOR_TYPES, ARGUMENT_TYPES, EVENT_CARDS, LOCATIONS } from '@metarchy/engine'
import {
  ARG_SKIN_IDS,
  AVATAR_IDS,
  POLITICIAN_PACK,
  SHOP_CATALOG,
  SKIN_CATALOG,
  argSkinItemId
} from '@metarchy/protocol'
import { afterEach, describe, expect, it } from 'vitest'
import {
  cyberpunkTheme,
  politicianLayerKeys,
  setTheme,
  themeAsset,
  themeById,
  themes
} from '../src/theme.js'

const PUBLIC_ROOT = path.resolve(__dirname, '../public')

describe('cyberpunk theme manifest', () => {
  it('covers every key the board scene and HUD address', () => {
    const required = [
      'logo',
      'backdrop.space',
      'backdrop.landing',
      'location.city',
      ...LOCATIONS.flatMap((id) => [
        `location.${id}`,
        `location.${id}.hint`,
        `location.${id}.active`,
        `location.${id}.closeup`
      ]),
      ...ACTOR_TYPES.flatMap((a) => [`actor.${a}`, `actor.${a}.head`]),
      ...ARGUMENT_TYPES.map((a) => `argument.${a}`),
      ...EVENT_CARDS.map((c) => `card.event.${c}`),
      'resource.product',
      'resource.electricity',
      'resource.recycling',
      'value.power',
      'value.art',
      'value.knowledge',
      'value.fame',
      'value.vp',
      'deck.event',
      'deck.action'
    ]
    for (const key of required) expect(() => themeAsset(key), key).not.toThrow()
  })

  it('every manifest URL resolves to a committed file', () => {
    for (const [key, url] of Object.entries(cyberpunkTheme.assets)) {
      const file = path.join(PUBLIC_ROOT, url)
      expect(existsSync(file), `${key} → ${url}`).toBe(true)
    }
  })

  it('unknown keys throw instead of silently rendering nothing', () => {
    expect(() => themeAsset('no.such.key')).toThrow(/no asset/)
  })

  it('ships every wardrobe layer the protocol catalog promises', () => {
    // Catalog ↔ manifest lockstep: a pack bump without a build:theme rerun fails here.
    const keys: string[] = []
    for (let b = 1; b <= POLITICIAN_PACK.bodies; b++) keys.push(`wardrobe.politician.body.${b}`)
    for (let g = 1; g <= POLITICIAN_PACK.costumes.groups; g++)
      for (let v = 1; v <= POLITICIAN_PACK.costumes.variants; v++)
        keys.push(`wardrobe.politician.costume.${g}.${v}`)
    for (let g = 1; g <= POLITICIAN_PACK.hair.groups; g++)
      for (let v = 1; v <= POLITICIAN_PACK.hair.variants; v++)
        keys.push(`wardrobe.politician.hair.${g}.${v}`)
    for (let g = 1; g <= POLITICIAN_PACK.accessories.groups; g++)
      for (let v = 1; v <= POLITICIAN_PACK.accessories.variants; v++)
        keys.push(`wardrobe.politician.accessory.${g}.${v}`)
    expect(keys.length).toBe(103)
    for (const key of keys) expect(() => themeAsset(key), key).not.toThrow()
  })

  it('ships a webp for every whole-figure skin in the protocol catalog', () => {
    // Catalog ↔ manifest lockstep: a new skin id without a build:skins rerun fails here.
    for (const [actor, ids] of Object.entries(SKIN_CATALOG))
      for (const id of ids)
        expect(() => themeAsset(`skin.${actor}.${id}`), `skin.${actor}.${id}`).not.toThrow()
  })

  it('ships art for every avatar id and every GATO shop good', () => {
    // AVATAR_IDS / SHOP_CATALOG ↔ manifest lockstep (build:avatars / build:skins
    // / build:arg-skins). A coin set sells all four coins, so all four must ship.
    for (const id of AVATAR_IDS) expect(() => themeAsset(`avatar.${id}`), id).not.toThrow()
    expect(() => themeAsset('currency.gato')).not.toThrow()
    for (const item of SHOP_CATALOG) {
      const keys =
        item.kind === 'avatar'
          ? [`avatar.${item.avatar}`]
          : item.kind === 'skin'
            ? [`skin.${item.actor}.${item.skin}`]
            : ARGUMENT_TYPES.map((a) => `argSkin.${item.argSkin}.${a}`)
      for (const key of keys) expect(() => themeAsset(key), `${item.id} → ${key}`).not.toThrow()
    }
  })

  it('keeps the free coins out of the shop and every alloy in it', () => {
    // The game's own art is never merchandise (author rule): the default coins
    // and the launch faces ship owned, and only alloys reach the shelf.
    const goods = new Set(SHOP_CATALOG.map((i) => i.id))
    for (const arg of ARGUMENT_TYPES) expect(goods.has(`argument.${arg}`)).toBe(false)
    for (const id of ARG_SKIN_IDS) expect(goods.has(argSkinItemId(id)), id).toBe(true)
    // The RSP coins are not sold as avatar faces either.
    for (const id of AVATAR_IDS) expect(ARGUMENT_TYPES).not.toContain(id)
  })

  it('layer keys stack body → costume → hair → accessories', () => {
    expect(
      politicianLayerKeys({
        body: 2,
        costume: [3, 4],
        hair: [5, 6],
        accessories: [
          [1, 7],
          [4, 2]
        ]
      })
    ).toEqual([
      'wardrobe.politician.body.2',
      'wardrobe.politician.costume.3.4',
      'wardrobe.politician.hair.5.6',
      'wardrobe.politician.accessory.1.7',
      'wardrobe.politician.accessory.4.2'
    ])
    // Bald and bare is a legal look: body + costume only.
    expect(politicianLayerKeys({ body: 1, costume: [1, 1] })).toHaveLength(2)
  })
})

describe('theme registry (art-style switcher)', () => {
  afterEach(() => setTheme(cyberpunkTheme))

  it('resolves persisted ids and falls back to the default style', () => {
    expect(themeById('cyberpunk')).toBe(cyberpunkTheme)
    expect(themeById('steampunk-not-installed')).toBe(cyberpunkTheme)
    expect(themeById(undefined)).toBe(cyberpunkTheme)
    expect(themes[0]).toBe(cyberpunkTheme)
  })

  it('partial themes inherit missing assets from the default style', () => {
    setTheme({ id: 'partial', name: 'Partial', assets: { logo: '/x/logo.png' } })
    expect(themeAsset('logo')).toBe('/x/logo.png')
    expect(themeAsset('actor.robot')).toBe(cyberpunkTheme.assets['actor.robot'])
    expect(() => themeAsset('no.such.key')).toThrow(/no asset/)
  })
})
